import { prisma } from "@/lib/prisma";
import AppShell from "@/components/AppShell";
import FeeForm from "./FeeForm";

export default async function FeesPage(){
 const [students,fees]=await Promise.all([prisma.student.findMany({orderBy:{name:"asc"}}),prisma.fee.findMany({include:{student:true},orderBy:{dueDate:"asc"}})]);
 return <AppShell><h1 className="title">Fees</h1><p className="subtitle">Track tuition and payment records.</p>
 <div style={{marginTop:20}}><FeeForm students={students.map(s=>({id:s.id,name:s.name,admissionNo:s.admissionNo}))}/></div>
 <div className="card" style={{marginTop:18}}><h2>Fee Records</h2><div className="table-wrap"><table><thead><tr><th>Student</th><th>Academic Year</th><th>Amount</th><th>Paid</th><th>Status</th><th>Due Date</th></tr></thead><tbody>
 {fees.map(f=><tr key={f.id}><td>{f.student.name}</td><td>{f.academicYear}</td><td>₹{f.amount.toLocaleString("en-IN")}</td><td>₹{f.paidAmount.toLocaleString("en-IN")}</td><td>{f.status}</td><td>{f.dueDate.toISOString().slice(0,10)}</td></tr>)}
 </tbody></table></div></div></AppShell>
}
